package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.gcd method.
 * Aiming for maximum branch and line coverage.
 */
public class MathUtils_gcd_TriageGen0Test {













    @Test
    public void testGcdOverflowArithmeticException() {
        // The code throws ArithmeticException if k reaches 31
        // This happens if both u and v are 2^31 (which is impossible for int, 
        // but since we use u/v as potentially negative, 
        // we check if the logic triggers the k == 31 check).
        // In Java, int cannot be 2^31. However, if u and v are 0, it returns early.
        // The only way to reach k=31 is if u and v are effectively 0 in terms of odd bits.
        // Since the loop condition is (u & 1) == 0 && (v & 1) == 0, 
        // if u = Integer.MIN_VALUE (-2^31) and v = Integer.MIN_VALUE, 
        // k will increment 31 times.

        assertThrows(ArithmeticException.class, () -> {
            MathUtils.gcd(Integer.MIN_VALUE, Integer.MIN_VALUE);
        });
    }

    // Helper for JUnit 4 to handle exception testing if not using modern JUnit
    private void assertThrows(Class<? extends Throwable> expectedException, Runnable runnable) {
        try {
            runnable.run();
            fail("Expected " + expectedException.getName() + " but no exception was thrown.");
        } catch (Throwable actualException) {
            if (!expectedException.isInstance(actualException)) {
                fail("Expected " + expectedException.getName() + " but caught " + actualException.getClass().getName());
            }
        }
    }
}
